77	// Provision ensures that i is set up properly before use.
78	//
79	// EXPERIMENTAL: Subject to change or removal.
80	func (irh *Intercept) Provision(ctx caddy.Context) error {
81		// set up any response routes
82		for i, rh := range irh.HandleResponse {
83			err := rh.Provision(ctx)
84			if err != nil {
85				return fmt.Errorf("provisioning response handler %d: %w", i, err)
86			}
87		}
88	
89		irh.logger = ctx.Logger()
90	
91		return nil
92	}
