164	func (enc *Encode) ServeHTTP(w http.ResponseWriter, r *http.Request, next caddyhttp.Handler) error {
165		if isEncodeAllowed(r.Header) {
166			for _, encName := range AcceptedEncodings(r, enc.Prefer) {
167				if _, ok := enc.writerPools[encName]; !ok {
168					continue // encoding not offered
169				}
170				w = enc.openResponseWriter(encName, w, r.Method == http.MethodConnect)
171				defer w.(*responseWriter).Close()
172	
173				// to comply with RFC 9110 section 8.8.3(.3), we modify the Etag when encoding
174				// by appending a hyphen and the encoder name; the problem is, the client will
175				// send back that Etag in an If-None-Match header, but upstream handlers that set
176				// the Etag in the first place don't know that we appended to their Etag! so here
177				// we have to strip our addition so the upstream handlers can still honor client
178				// caches without knowing about our changes...
179				if etags := r.Header.Values("If-None-Match"); len(etags) > 0 {
180					etag := strings.Join(etags, ", ")
181					stripped := strings.ReplaceAll(etag, "-"+encName+`"`, `"`)
182					if stripped != etag || len(etags) > 1 {
183						r.Header.Set("If-None-Match", stripped)
184					}
185				}
186	
187				break
188			}
189		}
190	
191		err := next.ServeHTTP(w, r)
192		// If there was an error, disable encoding completely
193		// This prevents corruption when handle_errors processes the response
194		if err != nil {
195			if ew, ok := w.(*responseWriter); ok {
196				ew.disabled = true
197			}
198		}
199	
200		return err
201	}
