362	func testH2ToH1ChunkedResponseServeH1(t *testing.T) *http.Server {
363		handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
364			if r.Host != "127.0.0.1:9443" {
365				t.Errorf("r.Host doesn't match, %v!", r.Host)
366				w.WriteHeader(http.StatusNotFound)
367				return
368			}
369	
370			if !strings.HasPrefix(r.URL.Path, "/tov2ray") {
371				w.WriteHeader(http.StatusNotFound)
372				return
373			}
374	
375			defer r.Body.Close()
376			bytes, err := io.ReadAll(r.Body)
377			if err != nil {
378				t.Fatalf("unable to read the response body %s", err)
379			}
380	
381			n := len(bytes)
382	
383			var writer io.Writer
384			if strings.Contains(r.Header.Get("Accept-Encoding"), "gzip") {
385				gw, err := gzip.NewWriterLevel(w, 5)
386				if err != nil {
387					t.Error("can't return gzip data")
388					w.WriteHeader(http.StatusInternalServerError)
389					return
390				}
391				defer gw.Close()
392				writer = gw
393				w.Header().Set("Content-Encoding", "gzip")
394				w.Header().Del("Content-Length")
395				w.WriteHeader(200)
396			} else {
397				writer = w
398			}
399			if n > 0 {
400				writer.Write(bytes[:])
401			}
402		})
