1234			return
1235		}
1236	
1237		status := wrec.Status()
1238		size := wrec.Size()
1239	
1240		repl.Set("http.response.status", status) // will be 0 if no response is written by us (Go will write 200 to client)
1241		repl.Set("http.response.size", size)
1242		repl.Set("http.response.duration", duration)
1243		repl.Set("http.response.duration_ms", duration.Seconds()*1e3) // multiply seconds to preserve decimal (see #4666)
