1264				continue
1265			}
1266	
1267			if fields == nil {
1268				userID, _ := repl.GetString("http.auth.user.id")
1269	
1270				reqBodyLength := 0
1271				if bodyReader != nil {
1272					reqBodyLength = bodyReader.Length
1273				}
1274	
1275				extra := ctx.Value(ExtraLogFieldsCtxKey).(*ExtraLogFields)
1276	
1277				hasWriteErr := writeErr != nil && *writeErr != nil
1278	
1279				fieldCount := 6
1280				if hasWriteErr {
1281					fieldCount++
1282				}
1283				fields = make([]zapcore.Field, 0, fieldCount+len(extra.fields))
1284				fields = append(
1285					fields,
1286					zap.Int("bytes_read", reqBodyLength),
1287					zap.String("user_id", userID),
1288					zap.Duration("duration", *duration),
1289					zap.Int("size", size),
1290					zap.Int("status", status),
1291					zap.Object("resp_headers", LoggableHTTPHeader{
1292						Header:               wrec.Header(),
1293						ShouldLogCredentials: shouldLogCredentials,
1294					}),
1295				)
