		if got := h.streamLevel(); got != zapcore.DebugLevel {
			t.Errorf("level = %v, want DEBUG", got)
		}
	})

	t.Run("no level", func(t *testing.T) {
		h := &Handler{logger: base, StreamLogs: &StreamLogs{SkipHandshake: true}}
		if err := h.provisionStreamLogs(caddy.Context{}); err != nil {
			t.Fatal(err)
		}
		if got := h.streamLevel(); got != zapcore.DebugLevel {
			t.Errorf("level = %v, want DEBUG", got)
		}
	})

	t.Run("level", func(t *testing.T) {
		h := &Handler{logger: base, StreamLogs: &StreamLogs{Level: "warn"}}
		if err := h.provisionStreamLogs(caddy.Context{}); err != nil {
			t.Fatal(err)
		}
		if got := h.streamLevel(); got != zapcore.WarnLevel {
			t.Errorf("level = %v, want WARN", got)
		}
		if h.streamLogger != base {
			t.Error("the stream logger should default to the logger of the handler")
		}
	})

	t.Run("invalid level", func(t *testing.T) {
		h := &Handler{logger: base, StreamLogs: &StreamLogs{Level: "loud"}}
		if err := h.provisionStreamLogs(caddy.Context{}); err == nil {
			t.Error("expected an error for an invalid level")
		}
	})

	t.Run("logger name", func(t *testing.T) {
		h := &Handler{logger: base, StreamLogs: &StreamLogs{LoggerName: "access"}}
		if err := h.provisionStreamLogs(caddy.Context{}); err != nil {
			t.Fatal(err)
		}
		if h.streamLogger == nil || h.streamLogger == base {
			t.Error("the stream logger should be the named logger")
		}
	})
}

func TestLoggerModuleID(t *testing.T) {
	if got := loggerModule("http.log.access").CaddyModule().ID; got != "http.log.access" {
		t.Errorf("ID = %q", got)
	}
}

func TestStreamLoggerOrDefault(t *testing.T) {
	base, named := zap.NewNop(), zap.NewNop()
	if got := (&Handler{logger: base}).streamLoggerOrDefault(); got != base {
		t.Error("an unprovisioned handler should use its logger")
	}
	if got := (&Handler{logger: base, streamLogger: named}).streamLoggerOrDefault(); got != named {
		t.Error("the stream logger should be preferred")
	}
}

