			streamLogs := "level info\nlogger_name access"
			if skipHandshake {
				streamLogs = "skip_handshake\n" + streamLogs
			}
			config := fmt.Sprintf(`{
				skip_install_trust
				admin localhost:2999
				http_port 9080
