// A WebSocket over HTTP/2 (RFC 8441 extended CONNECT) is proxied to an HTTP/1.1
// backend as an upgrade, and the data goes through both ways.
func TestH2ExtendedConnectWebSocket(t *testing.T) {
	startUpgradeBackend(t, streamBackendA)

	tester := caddytest.NewTester(t)
	tester.InitServer(fmt.Sprintf(`{
		skip_install_trust
		admin localhost:2999
		http_port     9080
		https_port    9443
		grace_period  1ns
	}

	localhost:9443 {
		reverse_proxy %s
	}
	`, streamBackendA), "caddyfile")

	tr := &http2.Transport{TLSClientConfig: &tls.Config{InsecureSkipVerify: true}} //nolint:gosec
	defer tr.CloseIdleConnections()

	r, w := io.Pipe()
	req, err := http.NewRequest(http.MethodConnect, "https://localhost:9443/ws", r)
	if err != nil {
		t.Fatal(err)
	}
	req.Header.Set(":protocol", "websocket")

	resp, err := tr.RoundTrip(req)
	if err != nil {
		t.Fatalf("extended CONNECT request failed: %v", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		t.Fatalf("status = %d, want 200", resp.StatusCode)
	}

	// don't hang if the data doesn't come back
	timer := time.AfterFunc(streamTestWait, func() { resp.Body.Close(); w.Close() })
	defer timer.Stop()

	for _, msg := range []string{"hello over h2", "and again"} {
		if _, err := io.WriteString(w, msg); err != nil {
			t.Fatalf("writing %q: %v", msg, err)
		}
		buf := make([]byte, len(msg))
		if _, err := io.ReadFull(resp.Body, buf); err != nil {
			t.Fatalf("reading the echo of %q: %v", msg, err)
		}
		if string(buf) != msg {
			t.Fatalf("echo = %q, want %q", buf, msg)
		}
	}
}

